from typing import Dict, Set

Graph = Dict[int, Set[int]]


def add_edge(g: Graph, u: int, v: int) -> None:
    g.setdefault(u, set()).add(v)
    g.setdefault(v, set()).add(u)


def dist(g: Graph, a: int, b: int) -> int:
    if a == b:
        return 0
    seen, fr = {a}, deque([(a, 0)])
    while fr:
        x, d = fr.popleft()
        for y in g.get(x, ()):
            if y == b:
                return d + 1
            if y not in seen:
                seen.add(y)
                fr.append((y, d + 1))
    raise ValueError("disconnected")


def diam(g: Graph, s: Set[int]) -> int:
    return max((dist(g, a, b) for a, b in combinations(s, 2)), default=0)


